"""Small independent bitstream utilities for lossless audio."""
class Bits:
    def __init__(self, data, pos=0):
        self.data=data
        self.pos=pos
    def read(self,n):
        if n==0:return 0
        p=self.pos; self.pos+=n
        a=p//8; b=(self.pos+7)//8
        return (int.from_bytes(self.data[a:b],'big') >> (b*8-self.pos)) & ((1<<n)-1)
    def signed(self,n):
        v=self.read(n)
        return v-(1<<n) if v&(1<<(n-1)) else v
    def unary(self):
        n=0
        while not self.read(1):
            n+=1
            if self.pos>len(self.data)*8:raise ValueError('Truncated bitstream')
        return n
    def align(self): self.pos=(self.pos+7)//8*8

class Writer:
    def __init__(self):self.out=bytearray();self.val=0;self.n=0
    def put(self,v,n):
        if not n:return
        self.val=(self.val<<n)|(v&((1<<n)-1));self.n+=n
        while self.n>=8:
            self.n-=8;self.out.append((self.val>>self.n)&255)
        self.val&=(1<<self.n)-1
    def unary(self,n):
        self.put(0,n);self.put(1,1)
    def finish(self):
        if self.n:self.put(0,8-self.n)
        return bytes(self.out)

def crc(data,bits,poly):
    c=0
    for x in data:
        c^=x<<(bits-8)
        for i in range(8):c=(c<<1)^ (poly if c&(1<<(bits-1)) else 0)
        c&=(1<<bits)-1
    return c
