        kind=data[pos];n=int.from_bytes(data[pos+1:pos+4],'big');val=data[pos+4:pos+4+n];pos+=n+4
        blocks.append((kind&127,val))
        if kind&127==0:info=val
        if kind&127==4:
            try:
                off=4+int.from_bytes(val[:4],'little');count=int.from_bytes(val[off:off+4],'little');off+=4
                for i in range(count):
                    l=int.from_bytes(val[off:off+4],'little');off+=4;s=val[off:off+l].decode(errors='replace');off+=l
                    k,v=s.split('=',1);comments[k]=v
            except Exception:pass
        if kind&128:break
    v=int.from_bytes(info[10:18],'big')
    return dict(rate=v>>44,channels=((v>>41)&7)+1,bps=((v>>36)&31)+1,total=v&((1<<36)-1),extradata=info,metadata=comments,offset=pos,blocks=blocks)

