        if r.read(14)!=0x3ffe:raise ValueError('Bad frame sync')
        r.read(1);strategy=r.read(1);bc=r.read(4);rc=r.read(4);ca=r.read(4);sc=r.read(3);r.read(1)
        b=r.read(8)
        if b&128:
            count=0
            while b&(0x80>>count):count+=1
            index=b&((1<<(7-count))-1)
            for i in range(count-1):index=(index<<6)|(r.read(8)&63)
        else:index=b
