        elif bc==6:sz=r.read(8)+1
        elif bc==7:sz=r.read(16)+1
        else:sz=256<<(bc-8)
        if rc==12:r.read(8)
        elif rc in [13,14]:r.read(16)
        r.read(8)
        bps={0:inf['bps'],1:8,2:12,4:16,5:20,6:24,7:32}.get(sc,inf['bps'])
        nchan=ca+1 if ca<8 else 2
        channel_data=[];subinfo=[]
        for c in range(nchan):
            cbps=bps+(1 if (ca==8 and c==1) or (ca==9 and c==0) or (ca==10 and c==1) else 0)
            r.read(1);typ=r.read(6);w=r.read(1);waste=r.unary()+1 if w else 0;cbps-=waste
            si={'type':typ,'wasted':waste,'bps':cbps}
            if typ==0:out=[r.signed(cbps)]*sz
            elif typ==1:out=[r.signed(cbps) for _ in range(sz)]
            else:
                if typ>=32:order=typ-31
                elif 8<=typ<=12:order=typ-8
                else:raise ValueError('Bad subframe')
                out=[r.signed(cbps) for _ in range(order)]
                if typ>=32:
                    precision=r.read(4)+1;shift=r.signed(5);co=[r.signed(precision) for _ in range(order)]
                    si.update(precision=precision,shift=shift,co=co)
                else:
                    co=[[],[1],[2,-1],[3,-3,1],[4,-6,4,-1]][order];shift=0
                method=r.read(2);po=r.read(4);ricebits=4+method;partsize=sz>>po;res=[];params=[]
                for j in range(1<<po):
                    k=r.read(ricebits);count=partsize-(order if j==0 else 0);params.append(k)
                    if k==(1<<ricebits)-1:
                        raw=r.read(5);res.extend(r.signed(raw) if raw else 0 for _ in range(count))
                    else:
                        for _ in range(count):
