        for key in ['ss','sseof','t','to']:
            if o.has(key):
                try:audio.duration(o.get(key))
                except:fail(f'Invalid duration for option {key}: {o.get(key)}\nError parsing options for output file {path}.\nError opening output files: Invalid argument')
        candidates=sources[:]
        if o.has('an'):candidates=[s for s in candidates if not isinstance(s,audio.Audio)]
