        for mp in o.all('map'):
            m=re.match(r'^(\d+)(?::(a|v|s|\d+))?(?::\d+)?(\?)?$',mp)
            if m:
                idx=int(m[1]);media=m[2];found=[sources[idx]] if idx<len(sources) else []
                if found and media=='v' and isinstance(found[0],audio.Audio):found=[]
                if found and media=='a' and not isinstance(found[0],audio.Audio):found=[]
