        if path not in ['-','pipe:','pipe:1'] and not path.startswith('/dev/'):
            realpath=path.removeprefix('file:')
            if os.path.exists(realpath):
                if glob.has('y') and glob.has('n'):fail('Error, both -y and -n supplied. Exiting.',234)
                if not glob.has('y'):
                    if not glob.has('n') and not glob.has('nostdin'):
                        log(f"File '{path}' already exists. Overwrite? [y/N] ",24)
                        try:answer=sys.stdin.readline().strip().lower()
                        except:answer=''
                        if answer in ['y','yes']:pass
                        else:log(f"Not overwriting - exiting",16);fail(f'Error opening output file {path}.',0)
